# Generate a WiX fragment that installs every DLL next to the exe (the FFmpeg
# shared build) as one component per file. Deterministic: components are
# numbered in file-name order, GUIDs are generated by WiX at build time.
#
#   powershell -File scripts/windows/gen-ffmpeg-wxs.ps1 -BinDir <dir with exe+dlls> -OutFile ffmpeg-files.wxs
#
# The fragment's ComponentGroup is referenced from the Binaries feature in
# crates/gui/wix/main.wxs; pass it to cargo-wix with --include.
param(
    [Parameter(Mandatory = $true)][string]$BinDir,
    [Parameter(Mandatory = $true)][string]$OutFile
)
$ErrorActionPreference = 'Stop'

$dlls = @(Get-ChildItem -LiteralPath $BinDir -Filter *.dll -File | Sort-Object Name)
if ($dlls.Count -eq 0) {
    throw "No DLLs found in $BinDir"
}

$components = for ($i = 0; $i -lt $dlls.Count; $i++) {
    $n = '{0:D3}' -f ($i + 1)
    $src = $dlls[$i].FullName -replace "'", "''"
    "      <Component Id='Ffmpeg$n' Guid='*'>"
    "        <File Source='$src' KeyPath='yes'/>"
    "      </Component>"
}

$xml = @(
    "<?xml version='1.0' encoding='windows-1252'?>"
    "<Wix xmlns='http://schemas.microsoft.com/wix/2006/wi'>"
    "  <Fragment>"
    "    <ComponentGroup Id='FfmpegGroup' Directory='Bin'>"
    $components
    "    </ComponentGroup>"
    "  </Fragment>"
    "</Wix>"
) -join "`r`n"

Set-Content -LiteralPath $OutFile -Value $xml -Encoding ASCII
Write-Host "Wrote $OutFile with $($dlls.Count) DLL components"
